mapper.update:
UPDATE employee
SET name = #{name},
    password = #{password},
    department_id = #{departmentId},
    post = #{post}
WHERE id = #{id}

mapper.select:
SELECT , d.id AS dept_id, d.name AS dept_name, d.address AS dept_address FROM employee e LEFT JOIN department d ON d.id = e.department_id
AND e.department_id = #{departmentId}
AND e.post = #{post}
